# -*- coding: utf-8 -*-
"""Documentación técnica de BUFINS (especificaciones, versiones, contenido, funcionalidades y ciberseguridad). Bilingüe con L.t(es, en)."""
from doc_lib import *

FECHA = '2026-11-08'


def doc_tecnica(L):
    t = L.t
    s = []

    # 1 ----------------------------------------------------------------------------------------------------------------
    s.append(('resumen', t('Resumen', 'Overview'), seccion('resumen', 1, t('Resumen del sistema', 'System overview'),
        t('<p class="lead"><b>BUFINS</b> es una plataforma web de gestión y análisis financiero para empresas y grupos empresariales: recibe la información contable en Excel, la valida, ejecuta modelos de cálculo y la presenta en informes gerenciales con apoyo de inteligencia artificial. Este documento reúne sus <b>especificaciones técnicas</b>, las <b>versiones actuales</b>, <b>qué contiene</b>, sus <b>funcionalidades</b> y los <b>controles de ciberseguridad</b>, para consultarlo ante cualquier duda técnica.</p>',
          '<p class="lead"><b>BUFINS</b> is a web platform for financial management and analysis for companies and business groups: it receives accounting data in Excel, validates it, runs calculation models and presents it in management reports supported by artificial intelligence. This document gathers its <b>technical specifications</b>, <b>current versions</b>, <b>what it contains</b>, its <b>features</b> and its <b>cybersecurity controls</b>, so it can be consulted for any technical question.</p>')
        + tabla([t('Dato', 'Item'), t('Valor', 'Value')], [
            [t('Aplicación', 'Application'), t('<b>Portal de clientes</b> (customers.bufins.com), proyecto <code>bufinscustomers</code>. Aparte existe el sitio público <b>bufins.com</b> (proyecto <code>bufinsweb</code>), con su propio código y despliegue.', '<b>Customer portal</b> (customers.bufins.com), project <code>bufinscustomers</code>. Separately there is the public site <b>bufins.com</b> (project <code>bufinsweb</code>), with its own code and deployment.')],
            [t('Plataforma', 'Platform'), t('ASP.NET Core MVC sobre <b>.NET 10</b> (LTS). Migrada desde ASP.NET MVC 5 / .NET Framework 4.8 el 2026-11-08; la versión anterior se conserva en la etiqueta de git <code>backup-net48-pre-migracion</code>.', 'ASP.NET Core MVC on <b>.NET 10</b> (LTS). Migrated from ASP.NET MVC 5 / .NET Framework 4.8 on 2026-11-08; the previous version is kept in the git tag <code>backup-net48-pre-migracion</code>.')],
            [t('Tamaño', 'Size'), t('Unas 47.000 líneas de C#, 59 controladores, 64 servicios, 31 ayudantes, 58 modelos y 87 vistas; unas 3.800 cadenas de texto por idioma.', 'About 47,000 lines of C#, 59 controllers, 64 services, 31 helpers, 58 models and 87 views; about 3,800 text strings per language.')],
            [t('Idiomas', 'Languages'), t('Español de Colombia (es-CO, por defecto) e inglés (en-US), con la elección guardada en una cookie.', 'Colombian Spanish (es-CO, default) and English (en-US), with the choice stored in a cookie.')],
            [t('Usuarios', 'Users'), t('Tres niveles: Usuario, Admin de Empresa y Super Admin, con datos aislados por empresa y acceso ampliado por grupo empresarial.', 'Three levels: User, Company Admin and Super Admin, with data isolated per company and access extended by business group.')],
            [t('Estado de este documento', 'Status of this document'), t('Fecha de actualización: <b>%s</b>. Los números de versión salen de los archivos del proyecto en esa fecha.' % FECHA, 'Update date: <b>%s</b>. Version numbers come from the project files on that date.' % FECHA)],
        ]))))

    # 2 ----------------------------------------------------------------------------------------------------------------
    s.append(('plataforma', t('Plataforma y versiones', 'Platform and versions'), seccion('plataforma', 2, t('Plataforma y versiones', 'Platform and versions'),
        '<h3>' + t('Servidor y base de datos', 'Server and database') + '</h3>'
        + tabla([t('Componente', 'Component'), t('Versión / especificación', 'Version / specification')], [
            [t('Runtime y lenguaje', 'Runtime and language'), t('.NET 10, C# (última versión del lenguaje), nulabilidad desactivada.', '.NET 10, C# (latest language version), nullability disabled.')],
            [t('Alojamiento', 'Hosting'), t('IIS con alojamiento <i>in-process</i> (ASP.NET Core Module). Paquete <b>autocontenido</b> para Windows x64 (incluye su propio .NET 10, unos 160 MB) porque el hosting compartido de Conexcol no lo trae. Panel Plesk.', 'IIS with <i>in-process</i> hosting (ASP.NET Core Module). <b>Self-contained</b> package for Windows x64 (it carries its own .NET 10, about 160 MB) because Conexcol’s shared hosting does not provide it. Plesk panel.')],
            [t('Base de datos', 'Database'), t('<b>SQL Server</b> (instancia actual 2016, nivel de compatibilidad 130). Todo el T-SQL se escribe para ser compatible con <b>SQL Server 2012 o superior</b>. Base <code>bufinscustomers</code>.', '<b>SQL Server</b> (current instance 2016, compatibility level 130). All T-SQL is written to be compatible with <b>SQL Server 2012 or later</b>. Database <code>bufinscustomers</code>.')],
            [t('Acceso a datos', 'Data access'), t('ADO.NET con <b>procedimientos almacenados</b> y consultas parametrizadas (Microsoft.Data.SqlClient 6.1.2). No se usa un ORM.', 'ADO.NET with <b>stored procedures</b> and parameterized queries (Microsoft.Data.SqlClient 6.1.2). No ORM is used.')],
            [t('Memoria', 'Memory'), t('Recolector de basura de estación de trabajo y no concurrente, con conservación de memoria: pico observado de unos 190 MB (el modo servidor llegaba a 309 MB).', 'Workstation, non-concurrent garbage collector with memory conservation: observed peak of about 190 MB (server mode reached 309 MB).')],
            [t('Correo', 'Email'), t('SMTP con MailKit 4.16.0; las cuentas de correo se administran desde la aplicación (Configuración → Cuentas de correo).', 'SMTP with MailKit 4.16.0; mail accounts are managed from the application (Settings → Mail accounts).')],
            [t('Inteligencia artificial', 'Artificial intelligence'), t('API de OpenAI (modelo por defecto <code>gpt-4o</code>, configurable). Todo pasa por un único punto (<code>IAGateway</code>) que mide el consumo.', 'OpenAI API (default model <code>gpt-4o</code>, configurable). Everything goes through a single point (<code>IAGateway</code>) that measures consumption.')],
        ])
        + '<h3>' + t('Paquetes (NuGet)', 'Packages (NuGet)') + '</h3>'
        + tabla([t('Paquete', 'Package'), t('Versión', 'Version'), t('Para qué se usa', 'What it is used for')], [
            ['Microsoft.Data.SqlClient', '6.1.2', t('Conexión a SQL Server', 'SQL Server connection')],
            ['ClosedXML', '0.105.0', t('Lectura y escritura de Excel (licencia MIT)', 'Excel reading and writing (MIT license)')],
            ['MailKit', '4.16.0', t('Envío de correo SMTP', 'SMTP email sending')],
            ['BCrypt.Net-Next', '4.0.3', t('Cifrado de contraseñas', 'Password hashing')],
            ['Newtonsoft.Json / Mvc.NewtonsoftJson', '13.0.3 / 10.0.0', t('Serialización JSON compatible con el formato histórico', 'JSON serialization compatible with the historical format')],
            ['NUglify', '1.21.15', t('Minificación de los paquetes de CSS y JS', 'Minification of the CSS and JS bundles')],
            ['System.Drawing.Common', '10.0.0', t('Procesamiento de imágenes (logos)', 'Image processing (logos)')],
            ['System.Runtime.Caching', '10.0.0', t('Cachés en memoria', 'In-memory caches')],
            ['System.Security.Cryptography.Pkcs', '10.0.14', t('Criptografía (compatibilidad de claves)', 'Cryptography (key compatibility)')],
        ])
        + '<h3>' + t('Navegador (interfaz)', 'Browser (interface)') + '</h3>'
        + tabla([t('Librería', 'Library'), t('Versión', 'Version'), t('Uso', 'Use')], [
            ['Bootstrap + SB Admin 2', '4.6.0 / 4.1.3', t('Diseño y componentes (con barra lateral propia)', 'Layout and components (with a custom sidebar)')],
            ['jQuery', '3.6.0', t('Interacción en pantalla y AJAX', 'Screen interaction and AJAX')],
            ['Chart.js', '4.4.1', t('Gráficos de los informes', 'Report charts')],
            ['jsPDF / html2canvas', '2.5.1 / 1.4.1', t('PDF y copia como imagen, generados en el navegador', 'PDF and copy-as-image, generated in the browser')],
            ['SweetAlert2', '11.19.1', t('Confirmaciones y avisos', 'Confirmations and alerts')],
            ['Select2', '4.1.0', t('Listas desplegables con búsqueda', 'Drop-down lists with search')],
            ['Font Awesome Free', '7.0.0', t('Iconos (solo fuentes woff2)', 'Icons (woff2 fonts only)')],
        ])
        + nota(L, '<b>Recomendación.</b> Bootstrap 4 ya no recibe actualizaciones de seguridad y jQuery 3.6.0 es anterior a la versión actual de esa rama. Es un trabajo de mantenimiento de interfaz que conviene planear (por ejemplo, subir a Bootstrap 5 y jQuery 3.7), con pruebas visuales de todas las pantallas.', '<b>Recommendation.</b> Bootstrap 4 no longer receives security updates and jQuery 3.6.0 is older than the current release of that branch. This is interface maintenance worth planning (for example moving to Bootstrap 5 and jQuery 3.7), with visual testing of every screen.'))))

    # 3 ----------------------------------------------------------------------------------------------------------------
    s.append(('arquitectura', t('Arquitectura', 'Architecture'), seccion('arquitectura', 3, t('Arquitectura', 'Architecture'),
        t('<p class="lead">Aplicación en capas, de una sola solución, sin servicios externos propios: el navegador habla con la aplicación y esta con SQL Server; las únicas salidas son el correo y la API de IA.</p>',
          '<p class="lead">A layered, single-solution application with no external services of its own: the browser talks to the application and the application to SQL Server; the only outbound calls are email and the AI API.</p>')
        + tabla([t('Capa', 'Layer'), t('Qué contiene', 'What it contains')], [
            ['Controllers', t('Reciben la petición, validan acceso y llaman a servicios. Todos heredan de <code>BaseController</code> (mensajes, traducción de textos, validación de acceso a IA).', 'Receive the request, validate access and call services. All inherit from <code>BaseController</code> (messages, text translation, AI access validation).')],
            ['Services', t('Lógica de negocio y acceso a SQL Server; heredan de <code>BaseService</code> (cadena de conexión).', 'Business logic and SQL Server access; inherit from <code>BaseService</code> (connection string).')],
            ['Models', t('Modelos de datos y de vista.', 'Data and view models.')],
            ['Views', t('Vistas Razor organizadas por área funcional (Configuración, Datos, Informes…), con layout, parciales compartidos y menú dinámico.', 'Razor views organized by functional area (Settings, Data, Reports…), with layout, shared partials and a dynamic menu.')],
            ['Helpers / Filters / Permisos', t('Ayudantes (sesión, empresas, tema, Excel, correo…), filtros globales y atributos de autorización (<code>ValidarSesion</code>, <code>RequierePermiso</code>, <code>SoloSuperAdmin</code>).', 'Helpers (session, companies, theme, Excel, email…), global filters and authorization attributes (<code>ValidarSesion</code>, <code>RequierePermiso</code>, <code>SoloSuperAdmin</code>).')],
            ['Compat / Infra', t('Capa de compatibilidad que conserva la forma de trabajar del sitio anterior (sesión, configuración, caché) y la infraestructura de arranque (paquetes CSS/JS, cabeceras de seguridad, rutas).', 'Compatibility layer that keeps the previous site’s way of working (session, configuration, cache) and the startup infrastructure (CSS/JS bundles, security headers, paths).')],
        ])
        + '<h3>' + t('Piezas transversales', 'Cross-cutting pieces') + '</h3><ul>'
        + t('<li><b>Sesión:</b> en memoria del servidor, 20 minutos de inactividad (deslizante), cookie <code>BUFINS_SessionId</code>; un aviso en pantalla a los 5 minutos y una renovación silenciosa mientras el usuario está activo.</li>', '<li><b>Session:</b> in server memory, 20 minutes of inactivity (sliding), cookie <code>BUFINS_SessionId</code>; an on-screen warning at 5 minutes and a silent renewal while the user is active.</li>')
        + t('<li><b>Configuración:</b> <code>appsettings.json</code> (valores no secretos) y <code>secretsSettings.json</code> (cadena de conexión y claves; fuera del repositorio y del paquete). Parámetros de negocio en la tabla <code>ConfiguracionSistema</code>, editables en pantalla.</li>', '<li><b>Configuration:</b> <code>appsettings.json</code> (non-secret values) and <code>secretsSettings.json</code> (connection string and keys; outside the repository and the package). Business parameters in the <code>ConfiguracionSistema</code> table, editable on screen.</li>')
        + t('<li><b>Registro (logs):</b> un archivo por día en <code>App_Data/logs</code> con retención de 30 días, con IP, usuario, URL y la cadena completa de excepciones.</li>', '<li><b>Logging:</b> one file per day in <code>App_Data/logs</code> with 30-day retention, including IP, user, URL and the full exception chain.</li>')
        + t('<li><b>Errores:</b> páginas de error de la marca (403, 404, 500) independientes de la sesión; al navegador solo llegan mensajes controlados con un código de referencia, nunca el detalle técnico.</li>', '<li><b>Errors:</b> branded error pages (403, 404, 500) independent of the session; only controlled messages with a reference code reach the browser, never the technical detail.</li>')
        + t('<li><b>Caché:</b> en memoria con vencimiento corto (empresas, escenarios, hojas de cargue, permisos) que se invalida al guardar.</li>', '<li><b>Cache:</b> in memory with short expiry (companies, scenarios, upload sheets, permissions) invalidated on save.</li>')
        + t('<li><b>Textos:</b> todo texto visible está en archivos de recursos en español e inglés; ninguna pantalla lleva texto fijo.</li></ul>', '<li><b>Texts:</b> every visible text lives in Spanish and English resource files; no screen carries hard-coded text.</li></ul>'))))

    # 4 ----------------------------------------------------------------------------------------------------------------
    s.append(('datos', t('Datos', 'Data'), seccion('datos', 4, t('Datos y flujo de la información', 'Data and information flow'),
        '<div class="flow">' + ''.join('<div class="node">%s</div>' % n for n in [
            t('Excel (plantilla)', 'Excel (template)'), t('Staging y validación', 'Staging and validation'), t('Tablas <code>Ini_*</code>', '<code>Ini_*</code> tables'),
            t('Modelos (procedimientos)', 'Models (procedures)'), t('Tablas <code>Modelo*</code>', '<code>Modelo*</code> tables'), t('Informes e IA', 'Reports and AI')]) + '</div>'
        + tabla([t('Grupo de datos', 'Data group'), t('Contenido', 'Content')], [
            [t('Cargue', 'Upload'), t('<code>Ini_*</code> (9 tablas estándar más las hojas personalizadas por empresa), sus espejos <code>Staging_Ini_*</code>, <code>CarguesLotes</code> y <code>CarguesLotesErrores</code>. El catálogo de hojas (<code>CargueHojas</code>) define qué hojas del Excel existen y a qué tabla van.', '<code>Ini_*</code> (9 standard tables plus company-specific sheets), their <code>Staging_Ini_*</code> mirrors, <code>CarguesLotes</code> and <code>CarguesLotesErrores</code>. The sheet catalog (<code>CargueHojas</code>) defines which Excel sheets exist and which table they go to.')],
            [t('Modelos', 'Models'), t('Ocho tablas materializadas que llenan los modelos: <code>ModeloPYG</code>, <code>ModeloBalance</code>, <code>ModeloBalancePpto</code>, <code>ModeloBalanceDiff</code>, <code>ModeloFlujoCaja</code>, <code>ModeloFlujoEfectivo</code>, <code>ModeloLineasNegocio</code> y <code>ModeloTesoreriaPpto</code>. Los procedimientos <code>sp_Modelo*</code> viven solo en la base de datos.', 'Eight materialized tables filled by the models: <code>ModeloPYG</code>, <code>ModeloBalance</code>, <code>ModeloBalancePpto</code>, <code>ModeloBalanceDiff</code>, <code>ModeloFlujoCaja</code>, <code>ModeloFlujoEfectivo</code>, <code>ModeloLineasNegocio</code> and <code>ModeloTesoreriaPpto</code>. The <code>sp_Modelo*</code> procedures live only in the database.')],
            [t('Relacionamientos', 'Mappings'), t('Tablas <code>Rel_*</code> que clasifican cuentas y líneas de cada informe (PYG, balance, tesorería, flujos…).', '<code>Rel_*</code> tables that classify accounts and lines of each report (P&amp;L, balance sheet, treasury, flows…).')],
            [t('Empresas y accesos', 'Companies and access'), t('<code>Empresas</code>, <code>GruposEmpresariales</code>, <code>Escenarios</code>, <code>Usuarios</code>, <code>UsuarioImagenes</code>, <code>MenuOpciones</code> y <code>UsuarioMenuPermisos</code>, <code>MenuOpcionesEmpresas</code>, <code>EmpresaLogos</code>, <code>EmpresaPaletas</code>.', '<code>Empresas</code>, <code>GruposEmpresariales</code>, <code>Escenarios</code>, <code>Usuarios</code>, <code>UsuarioImagenes</code>, <code>MenuOpciones</code> and <code>UsuarioMenuPermisos</code>, <code>MenuOpcionesEmpresas</code>, <code>EmpresaLogos</code>, <code>EmpresaPaletas</code>.')],
            [t('Seguridad', 'Security'), t('<code>UsuarioPasskeys</code>, <code>IntentosLoginIP</code>, <code>SolicitudesReinicioAuth</code> y las columnas de doble factor de <code>Usuarios</code>.', '<code>UsuarioPasskeys</code>, <code>IntentosLoginIP</code>, <code>SolicitudesReinicioAuth</code> and the two-factor columns of <code>Usuarios</code>.')],
            [t('Auditoría', 'Audit'), t('<code>Auditoria</code> (cambios y seguridad), <code>AuditoriaNavegacion</code>, <code>AuditoriaCargues</code>, <code>CargueDetalleAuditoria</code>, <code>AuditoriaAnalisisIA</code>.', '<code>Auditoria</code> (changes and security), <code>AuditoriaNavegacion</code>, <code>AuditoriaCargues</code>, <code>CargueDetalleAuditoria</code>, <code>AuditoriaAnalisisIA</code>.')],
            [t('Versiones y respaldos de cargues', 'Upload versions and backups'), t('<code>HistorialVersionesCargues</code> y <code>SnapshotsCargues</code> (instantáneas comprimidas), <code>RespaldosRestauracion</code>, <code>CargueArchivos</code>.', '<code>HistorialVersionesCargues</code> and <code>SnapshotsCargues</code> (compressed snapshots), <code>RespaldosRestauracion</code>, <code>CargueArchivos</code>.')],
            [t('IA, notificaciones y otros', 'AI, notifications and others'), t('<code>ConfigIAEmpresa</code>, <code>IAUsoLog</code>, <code>IAUsoMensual</code>, <code>Notificaciones</code>, <code>ComentariosGestion</code>, <code>IndicadoresUmbrales</code>, <code>DocumentacionAcceso</code>, <code>ConfiguracionSistema</code>.', '<code>ConfigIAEmpresa</code>, <code>IAUsoLog</code>, <code>IAUsoMensual</code>, <code>Notificaciones</code>, <code>ComentariosGestion</code>, <code>IndicadoresUmbrales</code>, <code>DocumentacionAcceso</code>, <code>ConfiguracionSistema</code>.')],
        ])
        + '<h3>' + t('Reglas de datos', 'Data rules') + '</h3><ul>'
        + t('<li><b>Escenarios:</b> cada empresa puede tener varias copias paralelas de sus datos (Escenario 1 es el principal); la configuración de la empresa es común.</li>', '<li><b>Scenarios:</b> each company can have several parallel copies of its data (Scenario 1 is the main one); the company configuration is shared.</li>')
        + t('<li><b>Los informes y la IA leen solo de las tablas <code>Modelo*</code></b>, nunca de las de cargue. Los informes no ejecutan modelos: muestran lo que el último modelo dejó.</li>', '<li><b>Reports and AI read only from the <code>Modelo*</code> tables</b>, never from the upload tables. Reports do not run models: they show what the last model left.</li>')
        + t('<li><b>Nunca se deja un año vacío:</b> cargues, restauraciones y recuperaciones comparten una regla que bloquea la operación si dejaría una tabla casi vacía.</li>', '<li><b>A year is never left empty:</b> uploads, restores and recoveries share a rule that blocks the operation if it would leave a table almost empty.</li>')
        + t('<li><b>T-SQL compatible con SQL Server 2012:</b> sin <code>STRING_AGG</code>, <code>TRIM</code>, funciones JSON ni <code>CREATE OR ALTER</code>.</li></ul>', '<li><b>T-SQL compatible with SQL Server 2012:</b> no <code>STRING_AGG</code>, <code>TRIM</code>, JSON functions or <code>CREATE OR ALTER</code>.</li></ul>'))))

    # 5 ----------------------------------------------------------------------------------------------------------------
    s.append(('funciones', t('Funcionalidades', 'Features'), seccion('funciones', 5, t('Módulos y funcionalidades', 'Modules and features'),
        tabla([t('Área', 'Area'), t('Qué ofrece', 'What it offers')], [
            [t('<b>Cargue de datos</b>', '<b>Data upload</b>'), t('Plantilla Excel generada por empresa; el archivo se valida primero en un área de pruebas (staging) con reglas y se confirma solo si no hay errores. Hallazgos exportables (Excel, PDF, imagen, correo). Historial de versiones con <b>deshacer</b>, respaldo automático antes de restaurar y auditoría detallada de cada cargue.', 'Company-specific Excel template; the file is first validated in a staging area with rules and confirmed only if there are no errors. Exportable findings (Excel, PDF, image, email). Version history with <b>undo</b>, automatic backup before restoring and detailed audit of each upload.')],
            [t('<b>Gestor de hojas de cargue</b>', '<b>Upload sheet manager</b>'), t('Define las hojas estándar y las personalizadas por empresa y crea las tablas desde la aplicación, sin desplegar código.', 'Defines the standard and company-specific sheets and creates the tables from the application, without deploying code.')],
            [t('<b>Ejecución de modelos</b>', '<b>Model execution</b>'), t('Ejecuta los procedimientos de cálculo por empresa, año y escenario; exporta los resultados a Excel y los envía por correo.', 'Runs the calculation procedures by company, year and scenario; exports the results to Excel and sends them by email.')],
            [t('<b>Informes gerenciales</b>', '<b>Management reports</b>'), t('Estado de resultados (PYG), Balance general, Tesorería del presupuesto, Flujo de caja, Flujo de efectivo, Indicadores con semáforo (27), Rentabilidad por línea de negocio, Informe mensual de gerencia, Línea de tiempo dinámica, Informe de modelos e Histórico de precios (personalizado). Todos con exportación a Excel, PDF, imagen y correo, paleta de colores elegible, logo de la empresa, comentarios de gestión y documentación propia.', 'Income statement (P&amp;L), Balance sheet, Budget treasury, Cash flow, Statement of cash flows, Indicators with traffic light (27), Business line profitability, Monthly management report, Dynamic timeline, Models report and Price history (custom). All with export to Excel, PDF, image and email, selectable color palette, company logo, management comments and their own documentation.')],
            [t('<b>Inteligencia artificial</b>', '<b>Artificial intelligence</b>'), t('Resúmenes de tres líneas en cada informe, «Pregúntale a este informe» y un análisis libre sobre las tablas de modelos. Control por empresa (acceso, funciones, topes y presupuesto mensual con política al agotarse) y observabilidad de uso y costos.', 'Three-line summaries in each report, “Ask this report” and a free analysis over the model tables. Per-company control (access, functions, limits and monthly budget with a policy when exhausted) and usage and cost observability.')],
            [t('<b>Administración</b>', '<b>Administration</b>'), t('Empresas (con logo, página web y colores corporativos), usuarios, permisos por opción de menú, gestor de menús (con opciones personalizadas por empresa), grupos empresariales, escenarios, prompts de IA, categorías y grupos de variables, supuestos del balance del presupuesto, relacionamientos.', 'Companies (with logo, website and corporate colors), users, permissions per menu option, menu manager (with company-specific options), business groups, scenarios, AI prompts, variable categories and groups, budget balance sheet assumptions, mappings.')],
            [t('<b>Seguridad de acceso</b>', '<b>Access security</b>'), t('Doble factor con aplicación autenticadora, passkeys, solicitudes de reinicio aprobadas por un Super Admin y pantalla de seguridad del usuario. Ver la sección de ciberseguridad.', 'Two-factor with an authenticator app, passkeys, reset requests approved by a Super Admin and a user security screen. See the cybersecurity section.')],
            [t('<b>Auditoría</b>', '<b>Audit</b>'), t('Registro central de cambios, navegación por usuario, cargues, consultas de IA y analítica del portal público, en un módulo con pestañas.', 'Central change log, navigation by user, uploads, AI queries and public-portal analytics, in a tabbed module.')],
            [t('<b>Notificaciones y página principal</b>', '<b>Notifications and home page</b>'), t('Campana de notificaciones internas, alertas del negocio, accesos rápidos, indicadores financieros y noticias.', 'Internal notifications bell, business alerts, quick links, financial indicators and news.')],
            [t('<b>Documentación</b>', '<b>Documentation</b>'), t('Documentación de cada informe en su propia cápsula y biblioteca «Documentación BUFINS» con control de qué documentos son solo para Super Admin; todo en español e inglés, con marca de agua y auditoría de cada consulta.', 'Documentation of each report in its own capsule and the “BUFINS Documentation” library with control over which documents are Super Admin only; everything in Spanish and English, with a watermark and audit of every view.')],
        ])
        + '<h3>' + t('Roles', 'Roles') + '</h3>'
        + tabla([t('Rol', 'Role'), t('Alcance', 'Scope')], [
            [t('Usuario (0)', 'User (0)'), t('Solo las opciones de menú asignadas y solo los datos de su empresa.', 'Only the assigned menu options and only its company’s data.')],
            [t('Admin de Empresa (1)', 'Company Admin (1)'), t('Como el anterior, y además administra usuarios y configuración de su empresa (y de su grupo empresarial).', 'Like the previous one, and also manages users and configuration of its company (and its business group).')],
            [t('Super Admin (2)', 'Super Admin (2)'), t('Todas las empresas y opciones; configuración global, seguridad, IA y documentación.', 'All companies and options; global configuration, security, AI and documentation.')],
        ])
        + nota(L, '<b>Grupos empresariales.</b> Los usuarios de una empresa que pertenece a un grupo tienen acceso de lectura <b>y escritura</b> a las demás empresas del mismo grupo, como si fueran propias. Crear o borrar empresas y grupos es exclusivo del Super Admin.', '<b>Business groups.</b> Users of a company that belongs to a group have read <b>and write</b> access to the other companies of the same group, as if they were their own. Creating or deleting companies and groups is exclusive to the Super Admin.'))))

    # 6 ----------------------------------------------------------------------------------------------------------------
    s.append(('seguridad', t('Ciberseguridad', 'Cybersecurity'), seccion('seguridad', 6, t('Ciberseguridad', 'Cybersecurity'),
        t('<p class="lead">Resumen de los controles vigentes, organizados por tema. El detalle de hallazgos y la hoja de ruta están en la «Documentación oficial de ciberseguridad» de la biblioteca.</p>',
          '<p class="lead">Summary of the controls in place, organized by topic. The findings detail and the roadmap are in the “Official cybersecurity documentation” of the library.</p>')
        + tabla([t('Tema', 'Topic'), t('Control', 'Control')], [
            [t('<b>Contraseñas</b>', '<b>Passwords</b>'), t('Cifrado con <b>BCrypt</b> (factor 12) y migración transparente de formatos antiguos. Política: mínimo 12 caracteres, complejidad, sin repeticiones ni contraseñas comunes, sin el nombre de usuario, y comprobación contra contraseñas filtradas (<i>Have I Been Pwned</i> por rango, sin enviar la contraseña). Al crear un usuario se puede exigir el cambio en el primer ingreso.', 'Hashing with <b>BCrypt</b> (cost 12) and transparent migration of old formats. Policy: minimum 12 characters, complexity, no repetitions or common passwords, not containing the username, and a check against leaked passwords (<i>Have I Been Pwned</i> by range, without sending the password). When creating a user, a change at first login can be required.')],
            [t('<b>Inicio de sesión</b>', '<b>Login</b>'), t('Tiempo de respuesta igual para usuario inexistente y contraseña errónea (sin enumeración por tiempo). Límite de intentos <b>por IP</b> con bloqueo temporal y un <b>modo defensivo</b> cuando hay un pico general de fallos; los bloqueos de cuentas reales avisan a los Super Admin.', 'Equal response time for a nonexistent user and a wrong password (no enumeration by timing). <b>Per-IP</b> attempt limit with a temporary block and a <b>defensive mode</b> when there is a general spike of failures; real-account lockouts notify the Super Admins.')],
            [t('<b>Doble factor</b>', '<b>Two-factor</b>'), t('Código de un solo uso (TOTP, RFC 6238) con aplicación autenticadora, exigido en <b>cada</b> inicio de sesión; protección contra reutilización del código y descarte tras 5 intentos errados. El secreto se guarda cifrado. Sin códigos de recuperación a propósito: si un usuario pierde sus métodos, lo reinicia un Super Admin tras verificar su identidad por otro canal.', 'One-time code (TOTP, RFC 6238) with an authenticator app, required at <b>every</b> login; protection against code reuse and discard after 5 wrong attempts. The secret is stored encrypted. No recovery codes on purpose: if a user loses their methods, a Super Admin resets them after verifying identity through another channel.')],
            [t('<b>Passkeys (WebAuthn)</b>', '<b>Passkeys (WebAuthn)</b>'), t('Método adicional opcional, con verificación propia de la firma, el origen y el reto; exige verificación del usuario. Registrar o quitar una requiere reconfirmar con el código de la aplicación y avisa por notificación y correo.', 'Optional additional method, with its own verification of the signature, origin and challenge; requires user verification. Registering or removing one requires reconfirming with the app code and sends a notification and an email.')],
            [t('<b>Recuperación</b>', '<b>Recovery</b>'), t('Solicitud de reinicio solo tras validar la contraseña, aprobada por un Super Admin (nadie aprueba la suya) con la evidencia de la solicitud; todo queda auditado y se avisa al usuario por correo.', 'Reset request only after validating the password, approved by a Super Admin (nobody approves their own) with the evidence of the request; everything is audited and the user is notified by email.')],
            [t('<b>Sesión y cookies</b>', '<b>Session and cookies</b>'), t('Sesión de 20 minutos de inactividad con cierre automático; cookie de sesión con <code>HttpOnly</code>, <code>SameSite=Lax</code> y <code>Secure</code> (en HTTPS); protección <b>antiforgery</b> en las acciones que cambian datos.', '20-minute inactivity session with automatic sign-out; session cookie with <code>HttpOnly</code>, <code>SameSite=Lax</code> and <code>Secure</code> (over HTTPS); <b>antiforgery</b> protection on the actions that change data.')],
            [t('<b>Cabeceras</b>', '<b>Headers</b>'), t('<code>Strict-Transport-Security</code> (1 año, subdominios), <code>X-Content-Type-Options: nosniff</code>, <code>X-Frame-Options: SAMEORIGIN</code>, <code>Referrer-Policy</code>, <code>Permissions-Policy</code> (cámara, micrófono y ubicación desactivados), <code>Cross-Origin-Opener-Policy</code> y una <b>Content-Security-Policy</b> estricta: los scripts solo se ejecutan si son del propio sitio o llevan un <b>nonce</b> (código único por petición), sin <code>unsafe-inline</code>; las violaciones se registran. Sin cabeceras que revelen el servidor.', '<code>Strict-Transport-Security</code> (1 year, subdomains), <code>X-Content-Type-Options: nosniff</code>, <code>X-Frame-Options: SAMEORIGIN</code>, <code>Referrer-Policy</code>, <code>Permissions-Policy</code> (camera, microphone and location disabled), <code>Cross-Origin-Opener-Policy</code> and a strict <b>Content-Security-Policy</b>: scripts only run if they come from the site itself or carry a <b>nonce</b> (a one-time code per request), with no <code>unsafe-inline</code>; violations are logged. No headers that reveal the server.')],
            [t('<b>Datos y archivos</b>', '<b>Data and files</b>'), t('Todo acceso a datos con parámetros (sin concatenar texto del usuario). Los archivos subidos se validan por su <b>contenido real</b> (firma de bytes), no por la extensión; los logos se redibujan y se limpian de metadatos; límite de 100 MB por carga.', 'All data access uses parameters (user text is never concatenated). Uploaded files are validated by their <b>actual content</b> (byte signature), not by extension; logos are redrawn and stripped of metadata; 100 MB limit per upload.')],
            [t('<b>Aislamiento entre empresas</b>', '<b>Isolation between companies</b>'), t('Cada consulta por empresa pasa por una única regla de acceso (propia más las de su grupo). Los lotes de cargue están aislados por identificador y un candado impide dos cargues simultáneos de la misma empresa, año, modo y escenario.', 'Every company-scoped query goes through a single access rule (own plus those of its group). Upload batches are isolated by identifier and a lock prevents two simultaneous uploads of the same company, year, mode and scenario.')],
            [t('<b>Cifrado de secretos</b>', '<b>Secret encryption</b>'), t('Las claves de IA y los secretos de doble factor se guardan cifrados con las claves de máquina de la aplicación. Cadena de conexión y claves viven fuera del repositorio y del paquete publicado.', 'AI keys and two-factor secrets are stored encrypted with the application’s machine keys. The connection string and keys live outside the repository and the published package.')],
            [t('<b>Auditoría</b>', '<b>Audit</b>'), t('Registro central de cambios (quién, cuándo, desde qué IP, valor anterior y nuevo), eventos de seguridad, navegación por usuario (retención de 90 días), cargues, envíos de correo y consultas a la documentación. Las acciones no pueden fallar silenciando al sistema: el registro nunca interrumpe la operación.', 'Central change log (who, when, from which IP, previous and new value), security events, navigation by user (90-day retention), uploads, email sending and documentation views. The log never interrupts the operation.')],
            [t('<b>Inteligencia artificial</b>', '<b>Artificial intelligence</b>'), t('La IA solo recibe cifras ya calculadas de las tablas de modelos (no datos de detalle ni de otras tablas); acceso, funciones y presupuesto se controlan por empresa y cada consulta se mide y audita.', 'AI only receives already-calculated figures from the model tables (no detailed data or other tables); access, functions and budget are controlled per company and every query is measured and audited.')],
            [t('<b>Documentación</b>', '<b>Documentation</b>'), t('Se sirve desde una carpeta no pública, exige sesión, lleva marca de agua con quién la consulta, no se guarda en caché, rechaza abrirse directo en una pestaña y cada consulta se audita. El Super Admin decide qué documentos son solo para Super Admin.', 'Served from a non-public folder, requires a session, carries a watermark with who is viewing it, is not cached, refuses to open directly in a tab and every view is audited. The Super Admin decides which documents are Super Admin only.')],
            [t('<b>Respaldo y recuperación</b>', '<b>Backup and recovery</b>'), t('Instantánea previa de cada cargue y versiones recuperables (las dos más recientes por empresa, año, modo y escenario), respaldo automático antes de restaurar, y respaldos completos del sitio antes de cada publicación.', 'A snapshot before each upload and recoverable versions (the two most recent per company, year, mode and scenario), an automatic backup before restoring, and full site backups before each deployment.')],
        ])
        + '<h3>' + t('Puntos conocidos y recomendaciones', 'Known points and recommendations') + '</h3><ul>'
        + t('<li><b>Política CSP:</b> es estricta desde el 2026-11-08. Todo evento o script nuevo debe respetarla (sin <code>onclick</code> en el HTML; los scripts en línea reciben el nonce automáticamente). El parámetro <code>CspScriptEstricto</code> en «false» es un interruptor de emergencia que devuelve la política anterior sin republicar.</li>', '<li><b>CSP policy:</b> it has been strict since 2026-11-08. Any new event or script must respect it (no <code>onclick</code> in the HTML; inline scripts automatically get the nonce). The <code>CspScriptEstricto</code> parameter set to “false” is an emergency switch that restores the previous policy without redeploying.</li>')
        + t('<li><b>Librerías de interfaz:</b> Bootstrap 4.6 y jQuery 3.6 son anteriores a las versiones actuales (ver sección 2).</li>', '<li><b>Interface libraries:</b> Bootstrap 4.6 and jQuery 3.6 are older than the current versions (see section 2).</li>')
        + t('<li><b>Sesión en memoria:</b> un reinicio del sitio o un despliegue cierra todas las sesiones; el diseño es de un solo servidor.</li>', '<li><b>In-memory session:</b> restarting the site or deploying closes all sessions; the design is single-server.</li>')
        + t('<li><b>Llaves de protección de datos:</b> en el hosting actual la identidad del sitio no puede crear archivos en su carpeta, así que viven en memoria (un reinicio invalida formularios abiertos). Se pidió el permiso al proveedor.</li>', '<li><b>Data-protection keys:</b> on the current hosting the site identity cannot create files in its folder, so they live in memory (a restart invalidates open forms). Permission was requested from the provider.</li>')
        + t('<li><b>Publicación:</b> el certificado de Web Deploy del proveedor es autofirmado y se acepta de forma explícita en el perfil de publicación.</li>', '<li><b>Deployment:</b> the provider’s Web Deploy certificate is self-signed and is explicitly accepted in the publish profile.</li>')
        + t('<li><b>Credenciales:</b> rotar periódicamente la contraseña de SQL y actualizarla en <code>secretsSettings.json</code> del servidor (el cambio exige reiniciar el sitio).</li>', '<li><b>Credentials:</b> rotate the SQL password periodically and update it in the server’s <code>secretsSettings.json</code> (the change requires restarting the site).</li>')
        + t('<li><b>Pruebas:</b> no hay pruebas automáticas; la verificación se hace comparando pantallas y respuestas contra el sistema anterior y con sesiones reales.</li></ul>', '<li><b>Testing:</b> there are no automated tests; verification is done by comparing screens and responses against the previous system and with real sessions.</li></ul>'))))

    # 7 ----------------------------------------------------------------------------------------------------------------
    s.append(('operacion', t('Operación', 'Operations'), seccion('operacion', 7, t('Operación y publicación', 'Operations and deployment'),
        '<h3>' + t('Cómo se publica', 'How it is published') + '</h3>'
        + tabla([t('Paso', 'Step'), t('Qué se hace', 'What is done')], [
            ['1', t('Generar el paquete autocontenido (<code>dotnet publish</code>, Release, win-x64).', 'Build the self-contained package (<code>dotnet publish</code>, Release, win-x64).')],
            ['2', t('<b>Respaldar</b> el sitio actual completo con el script de despliegue (copia local por Web Deploy).', '<b>Back up</b> the whole current site with the deployment script (local copy through Web Deploy).')],
            ['3', t('Si cambiaron las claves o la cadena de conexión: subir <code>secretsSettings.json</code> y <b>reiniciar</b> el sitio.', 'If the keys or connection string changed: upload <code>secretsSettings.json</code> and <b>restart</b> the site.')],
            ['4', t('<b>Simular</b> la publicación (muestra qué crearía, cambiaría y borraría, sin tocar nada) y revisarla.', '<b>Simulate</b> the deployment (shows what it would create, change and delete, without touching anything) and review it.')],
            ['5', t('<b>Publicar</b>: el sitio muestra una página de mantenimiento unos minutos mientras se copian los archivos; no se tocan los secretos, las llaves, los logs ni los archivos del panel.', '<b>Deploy</b>: the site shows a maintenance page for a few minutes while the files are copied; secrets, keys, logs and panel files are not touched.')],
            ['6', t('Pruebas de humo con una sesión real (inicio de sesión con doble factor, el menú y varios informes). Si algo falla: <b>restaurar</b> el respaldo.', 'Smoke tests with a real session (login with two-factor, the menu and several reports). If something fails: <b>restore</b> the backup.')],
        ])
        + '<h3>' + t('Mantenimiento', 'Maintenance') + '</h3><ul>'
        + t('<li><b>Scripts SQL:</b> los cambios de estructura se entregan como scripts numerados que ejecuta el responsable en SQL Server; una vez aplicados se retiran del repositorio.</li>', '<li><b>SQL scripts:</b> structure changes are delivered as numbered scripts run by the owner in SQL Server; once applied they are removed from the repository.</li>')
        + t('<li><b>Limpieza automática:</b> los lotes de cargue sin confirmar se descartan solos (al salir, al cerrar sesión y por vencimiento); las notificaciones de más de 30 días y la navegación de más de 90 días se purgan de forma oportunista, sin tareas programadas.</li>', '<li><b>Automatic cleanup:</b> unconfirmed upload batches are discarded on their own (on leaving, on sign-out and by expiry); notifications older than 30 days and navigation older than 90 days are purged opportunistically, with no scheduled jobs.</li>')
        + t('<li><b>Agregar un informe:</b> servicio + controlador + vista, opción en el gestor de menús, texto en los dos idiomas, exportación estándar, paleta, logo, cápsula de documentación y entrada en el catálogo de documentación.</li>', '<li><b>Adding a report:</b> service + controller + view, option in the menu manager, text in both languages, standard export, palette, logo, documentation capsule and an entry in the documentation catalog.</li>')
        + t('<li><b>Documentación:</b> los documentos se generan con los scripts de <code>Tools/Documentacion</code>; el español y el inglés se mantienen juntos.</li></ul>', '<li><b>Documentation:</b> documents are generated with the scripts in <code>Tools/Documentacion</code>; Spanish and English are maintained together.</li></ul>'))))

    # 8 ----------------------------------------------------------------------------------------------------------------
    s.append(('faq', t('Preguntas frecuentes', 'FAQ'), '<section id="faq"><h2>8. ' + t('Preguntas frecuentes', 'Frequently asked questions') + '</h2>' + faq([
        (t('¿Qué versión de .NET usa y hasta cuándo tiene soporte?', 'Which .NET version does it use and until when is it supported?'), t('.NET 10, una versión de soporte a largo plazo (LTS). El soporte lo define Microsoft; conviene revisarlo al planear la próxima actualización.', '.NET 10, a long-term support (LTS) release. Support is defined by Microsoft; it is worth checking when planning the next update.')),
        (t('¿Dónde está alojado?', 'Where is it hosted?'), t('En un hosting compartido de Conexcol (Windows/IIS con Plesk), con acceso a SQL Server. Se publica por Web Deploy.', 'On a shared Conexcol hosting (Windows/IIS with Plesk), with access to SQL Server. It is deployed through Web Deploy.')),
        (t('¿Cómo se protegen los datos de una empresa frente a otra?', 'How is one company’s data protected from another’s?'), t('Cada consulta pasa por una regla de acceso por empresa y grupo; solo el Super Admin ve todas. Ver «Aislamiento entre empresas».', 'Every query goes through a company and group access rule; only the Super Admin sees all. See “Isolation between companies”.')),
        (t('¿Qué pasa si se pierde el celular del segundo factor?', 'What happens if the second-factor phone is lost?'), t('El usuario pide el reinicio desde la pantalla de verificación; un Super Admin lo aprueba tras verificar su identidad por otro canal.', 'The user requests a reset from the verification screen; a Super Admin approves it after verifying identity through another channel.')),
        (t('¿Qué datos recibe la inteligencia artificial?', 'What data does the artificial intelligence receive?'), t('Solo cifras ya calculadas de las tablas de modelos de la empresa consultada; nunca datos de detalle del cargue.', 'Only already-calculated figures from the model tables of the queried company; never detailed upload data.')),
        (t('¿Cómo se vuelve atrás si una publicación falla?', 'How do you roll back if a deployment fails?'), t('Con el respaldo completo hecho antes de publicar, que se restaura con el mismo script.', 'With the full backup made before deploying, restored with the same script.')),
        (t('¿Quién puede ver este documento?', 'Who can see this document?'), t('Por defecto solo el Super Admin. En la biblioteca «Documentación BUFINS» se marca u oculta cada documento como «solo Super Admin».', 'By default only the Super Admin. In the “BUFINS Documentation” library each document is marked or unmarked as “Super Admin only”.')),
    ]) + '</section>'))
    return (t('Documentación técnica de BUFINS', 'BUFINS technical documentation'),
            t('Especificaciones técnicas, versiones actuales, contenido, funcionalidades y ciberseguridad del sistema.', 'Technical specifications, current versions, content, features and cybersecurity of the system.'), s)
